function getCart(){const raw=localStorage.getItem("cart");return raw?JSON.parse(raw):[]}
function saveCart(cart){localStorage.setItem("cart",JSON.stringify(cart));updateCartDisplay()}
function updateCartDisplay(){const cart=getCart();const count=cart.reduce((sum,item)=>sum+item.qty,0);const el=document.getElementById("cart-count");if(el)el.textContent=count}
async function addToCart(productId){const resp=await fetch("/data/products.json");const data=await resp.json();const product=data.products.find((p)=>p.id==productId);if(!product)return;const cart=getCart();const existing=cart.find((item)=>item.id===product.id);if(existing){existing.qty+=1}else{cart.push({...product,qty:1})}
saveCart(cart);alert(`${product.title} added to cart`)}
function showCart(){const container=document.getElementById("cart-container");if(!container)return;const cart=getCart();if(cart.length===0){container.innerHTML="<p>Your cart is empty.</p>";return}
let html='<table class="table table-striped"><thead><tr><th>Product</th><th>Price</th><th>Qty</th><th>Total</th></tr></thead><tbody>';let total=0;cart.forEach((item)=>{const subtotal=item.price*item.qty;total+=subtotal;html+=`<tr>
      <td>${item.title}</td>
      <td>€${item.price}</td>
      <td>${item.qty}</td>
      <td>€${subtotal.toFixed(2)}</td>
    </tr>`});html+=`</tbody></table>
    <div class="mt-3">
      <h3>Total: €${total.toFixed(2)}</h3>
      <button onclick="checkout()" class="btn btn-success">Checkout</button>
    </div>`;container.innerHTML=html}
async function checkout(){const cart=getCart();const total=cart.reduce((sum,item)=>sum+item.price*item.qty,0);try{const resp=await fetch("/checkout",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({items:cart,total}),});const result=await resp.json();if(result.success){alert("Purchase successful!");localStorage.removeItem("cart");updateCartDisplay();showCart()}else{alert("Checkout failed.")}}catch(err){alert("Error during checkout.")}}
document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".add-to-cart").forEach((btn)=>{btn.onclick=()=>addToCart(btn.dataset.id)});showCart();updateCartDisplay()});var email=document.getElementById("floatingInput");var message=document.getElementById("floatingMessage");var contactBtn=document.getElementById("contactBtn");var dataJson=document.getElementById("dataJson");contactBtn.onclick=function(){if(email.value===""||message.value===""){alert("Please fill in all fields.");return}else{var userObj={email:email.value,message:message.value,};var userJson=JSON.stringify(userObj);localStorage.setItem("contactData",userJson);let text=localStorage.getItem("contactData");let object=JSON.parse(text);console.log(object.email);console.log(object.message);email.value="";message.value="";alert("Thank you for reaching out! We have received your message and will get back to you shortly.")}};async function fetchProducts(){const path="/data/products.json";const response=await fetch(path);const data=await response.json();return data}
async function fetchTopSellers(){const path="/data/topSellers.json";const response=await fetch(path);const data=await response.json();console.log("TOP SELLERS DATA",data);return data}
function renderTopSellers(bestSellersList){const el=document.getElementById("topTitle1");if(!el)return;document.getElementById("topTitle1").textContent=bestSellersList.products[0].title;document.getElementById("topTitle2").textContent=bestSellersList.products[1].title;document.getElementById("topTitle3").textContent=bestSellersList.products[2].title;document.getElementById("topPrice1").textContent=`€`+bestSellersList.products[0].price;document.getElementById("topPrice2").textContent=`€`+bestSellersList.products[1].price;document.getElementById("topPrice3").textContent=`€`+bestSellersList.products[2].price;document.getElementById("topImage1").src=bestSellersList.products[0].image;document.getElementById("topImage2").src=bestSellersList.products[1].image;document.getElementById("topImage3").src=bestSellersList.products[2].image;document.getElementById("topGenre1").textContent=bestSellersList.products[0].genre;document.getElementById("topGenre2").textContent=bestSellersList.products[1].genre;document.getElementById("topGenre3").textContent=bestSellersList.products[2].genre;document.getElementById("topDescription1").textContent=bestSellersList.products[0].description;document.getElementById("topDescription2").textContent=bestSellersList.products[1].description;document.getElementById("topDescription3").textContent=bestSellersList.products[2].description}
function renderProducts(productsList){const el=document.getElementById("title1");if(!el)return;document.getElementById("title1").textContent=productsList.products[0].title;document.getElementById("title2").textContent=productsList.products[1].title;document.getElementById("title3").textContent=productsList.products[2].title;document.getElementById("title4").textContent=productsList.products[3].title;document.getElementById("title5").textContent=productsList.products[4].title;document.getElementById("title6").textContent=productsList.products[5].title;document.getElementById("genre1").textContent=productsList.products[0].genre;document.getElementById("genre2").textContent=productsList.products[1].genre;document.getElementById("genre3").textContent=productsList.products[2].genre;document.getElementById("genre4").textContent=productsList.products[3].genre;document.getElementById("genre5").textContent=productsList.products[4].genre;document.getElementById("genre6").textContent=productsList.products[5].genre;document.getElementById("price1").textContent=`€`+productsList.products[0].price;document.getElementById("price2").textContent=`€`+productsList.products[1].price;document.getElementById("price3").textContent=`€`+productsList.products[2].price;document.getElementById("price4").textContent=`€`+productsList.products[3].price;document.getElementById("price5").textContent=`€`+productsList.products[4].price;document.getElementById("price6").textContent=`€`+productsList.products[5].price;document.getElementById("description1").textContent=productsList.products[0].description;document.getElementById("description2").textContent=productsList.products[1].description;document.getElementById("description3").textContent=productsList.products[2].description;document.getElementById("description4").textContent=productsList.products[3].description;document.getElementById("description5").textContent=productsList.products[4].description;document.getElementById("description6").textContent=productsList.products[5].description;document.getElementById("image1").src=productsList.products[0].image;document.getElementById("image2").src=productsList.products[1].image;document.getElementById("image3").src=productsList.products[2].image;document.getElementById("image4").src=productsList.products[3].image;document.getElementById("image5").src=productsList.products[4].image;document.getElementById("image6").src=productsList.products[5].image}
window.onload=async function(){const products=await fetchProducts();const topSellers=await fetchTopSellers();renderProducts(products);renderTopSellers(topSellers)};function logout(){localStorage.removeItem("loggedInUser");window.location.href="/login"}
document.addEventListener("DOMContentLoaded",function(){const loginForm=document.getElementById("login-form");const registerForm=document.getElementById("register-form");const showRegisterLink=document.getElementById("show-register");const showLoginLink=document.getElementById("show-login");showRegisterLink.addEventListener("click",function(e){e.preventDefault();loginForm.style.display="none";registerForm.style.display="block"});showLoginLink.addEventListener("click",function(e){e.preventDefault();registerForm.style.display="none";loginForm.style.display="block"});const registerFormElement=document.querySelector("#register-form form");registerFormElement.addEventListener("submit",function(e){e.preventDefault();const name=document.getElementById("register-name").value;const email=document.getElementById("register-email").value;const password=document.getElementById("register-password").value;const confirmPassword=document.getElementById("register-confirm-password").value;if(password.length<6){alert("Password must be at least 6 characters long");return}
if(password!==confirmPassword){alert("Passwords do not match");return}
const users=JSON.parse(localStorage.getItem("users"))||[];const userExists=users.some((user)=>user.email===email);if(userExists){alert("User already exists");return}
users.push({name,email,password});localStorage.setItem("users",JSON.stringify(users));alert("Registration successful! You can now log in.");registerForm.style.display="none";loginForm.style.display="block"});const loginFormElement=document.querySelector("#login-form form");loginFormElement.addEventListener("submit",function(e){e.preventDefault();const email=document.getElementById("login-email").value;const password=document.getElementById("login-password").value;const users=JSON.parse(localStorage.getItem("users"))||[];const user=users.find((user)=>user.email===email&&user.password===password);if(!user){alert("Invalid email or password");return}
localStorage.setItem("loggedInUser",JSON.stringify(user));alert("Login successful!");window.location.href="/"})})